func sqlIntegerCompare(left, right SqlInteger) SqlInteger {
	if left.Error != "" {
		return left
	}
	if right.Error != "" {
		return right
	}
	if !left.Valid || !right.Valid {
		return SqlInteger{}
	}
	var order int64
	if left.Value < right.Value {
		order = -1
	} else if left.Value > right.Value {
		order = 1
	}
	return SqlInteger{Value: order, Valid: true}
}

