	x, wx := sqlDecimalMathDigits(a.Value)
	y, wy := sqlDecimalMathDigits(b.Value)
	if len(x) > len(y) {
		x, y = y, x
		wx, wy = wy, wx
	}
	if len(x) == 0 {
		return SqlDecimalMath{Scale: scale}
	}
	nx, ny := len(x), len(y)
	px, py := (nx+1)/2, (ny+1)/2
	full := (nx+ny)/2 + 1
	offset := full - px - py + 1
	weight := wx + wy + 1 + 2*full - nx - ny - nx%2 - ny%2
